+
+  describe('Ciclo TDD E — criação válida, persistência e R29', () => {
+    it('cria atividade válida com org-ana, gerando IDs com prefixos corretos e status 201', async () => {
+      const res = await request(app)
+        .post('/atividades')
+        .set('X-Usuario', 'org-ana')
