  describe('Ciclo TDD D — sala inexistente R26', () => {
    it('salaId inexistente -> 404 NAO_ENCONTRADO', async () => {
      const res = await request(app)
        .post('/atividades')
        .set('X-Usuario', 'org-ana')
        .send({
          titulo: 'Introdução ao TypeScript',
          tipo: 'palestra',
          salaId: 'sala-inexistente',
