export class DomainError extends Error {
  constructor(public code: string, message: string) {
    super(message);
    this.name = 'DomainError';
  }
}

export interface ActivityData {
  id: string;
  titulo: string;
  tipo: string;
  salaId: string;
  vagas: number;
  cargaHorariaMinutos: number;
  cancelada: number;
  encontros: Array<{ id: string; inicio: string; fim: string }>;
}

export function validateActivityEncounterCount(tipo: string, encontrosCount: number): void {
  if (tipo === 'palestra' && encontrosCount !== 1) {
    throw new DomainError('QUANTIDADE_DE_ENCONTROS', 'Palestra deve ter exatamente 1 encontro');
  }
  if (tipo === 'minicurso' && (encontrosCount < 2 || encontrosCount > 5)) {
    throw new DomainError('QUANTIDADE_DE_ENCONTROS', 'Minicurso deve ter entre 2 e 5 encontros');
  }
}

export function calculateCargaHoraria(encontros: Array<{ inicio: string; fim: string }>): number {
  let total = 0;
  for (const enc of encontros) {
    const duracaoMs = new Date(enc.fim).getTime() - new Date(enc.inicio).getTime();
    total += Math.round(duracaoMs / 60000);
  }
  return total;
}

import crypto from 'node:crypto';
import { RoomRepository } from '../repositories/room-repository.js';
import { ActivityRepository } from '../repositories/activity-repository.js';
import { validateActivityEncounterCount, calculateCargaHoraria, ActivityData } from '../domain/activity.js';

export class NotFoundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'NotFoundError';
  }
}

export class CreateActivityUseCase {
  constructor(
    private activityRepository: ActivityRepository,
    private roomRepository: RoomRepository
  ) {}

  execute(input: {
    titulo: string;
    tipo: string;
    salaId: string;
    vagas: number;
    encontros: Array<{ inicio: string; fim: string }>;
  }): ActivityData {
    const room = this.roomRepository.findById(input.salaId);
    if (!room) {
      throw new NotFoundError('Sala não encontrada');
    }

    validateActivityEncounterCount(input.tipo, input.encontros.length);

    const atvId = 'atv_' + crypto.randomBytes(4).toString('hex');
    const encontrosWithIds = input.encontros.map(enc => ({
      id: 'enc_' + crypto.randomBytes(4).toString('hex'),
      inicio: enc.inicio,
      fim: enc.fim
    }));

    const cargaHorariaMinutos = calculateCargaHoraria(input.encontros);

    this.activityRepository.create({
      id: atvId,
      titulo: input.titulo,
      tipo: input.tipo,
      salaId: input.salaId,
      vagas: input.vagas,
      cargaHorariaMinutos,
      encontros: encontrosWithIds
    });

    const created: ActivityData = {
      id: atvId,
      titulo: input.titulo,
      tipo: input.tipo,
      salaId: input.salaId,
      vagas: input.vagas,
      cargaHorariaMinutos,
      cancelada: 0,
      encontros: encontrosWithIds
    };

    return created;
  }
}

import { M2IntegrationPort } from '../integrations/m2-port.js';
import { ActivityData } from '../domain/activity.js';

export function mapActivityResponse(
  atv: ActivityData,
  m2Port: M2IntegrationPort
) {
  const ocupadas = m2Port.getOcupadas(atv.id);
  const emEspera = m2Port.getEmEspera(atv.id);
  return {
    id: atv.id,
    titulo: atv.titulo,
    tipo: atv.tipo,
    salaId: atv.salaId,
    vagas: atv.vagas,
    cargaHorariaMinutos: atv.cargaHorariaMinutos,
    situacao: atv.cancelada ? 'cancelada' : 'prevista',
    ocupadas,
    vagasRestantes: atv.vagas - ocupadas,
    emEspera,
    encontros: atv.encontros
  };
}

