           titulo: 'Uma Vaga',
           tipo: 'palestra',
           salaId: 'sala-101',
           vagas: 1,
           encontros: [{ inicio: '2026-10-19T09:00:00-03:00', fim: '2026-10-19T10:00:00-03:00' }]
         });

       expect(res.status).toBe(201);
       expect(res.body.vagas).toBe(1);
     });

